import js from "@eslint/js";
import globals from "globals";
import tseslint from "typescript-eslint";
import { defineConfig } from "eslint/config";

export default defineConfig([
  {
    files: ["**/*.{js,mjs,cjs,ts,mts,cts}"],
    plugins: { js },
    extends: ["js/recommended"],
    languageOptions: {
      globals: {
        ...globals.browser,
        ...globals.node,
      },
    },
  },
  ...tseslint.configs.recommended,
  {
    // Typed rules below (no-floating-promises, require-await) need type information.
    // Without this block ESLint crashes on the first .ts file it lints.
    files: ["**/*.{ts,mts,cts}"],
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
  },
  {
    rules: {
      // Prevent console.log in production code
      "no-console": ["warn", { allow: ["warn", "error"] }],

      // Enforce explicit any types to be documented
      "@typescript-eslint/no-explicit-any": "warn",

      // Prevent unused variables
      "@typescript-eslint/no-unused-vars": [
        "error",
        {
          argsIgnorePattern: "^_",
          varsIgnorePattern: "^_",
        },
      ],

      // Require return types on functions
      "@typescript-eslint/explicit-function-return-type": [
        "warn",
        {
          allowExpressions: true,
          allowTypedFunctionExpressions: true,
        },
      ],

      // Prevent empty functions
      "@typescript-eslint/no-empty-function": "warn",

      // Enforce consistent naming conventions
      "@typescript-eslint/naming-convention": [
        "warn",
        {
          selector: "interface",
          format: ["PascalCase"],
          custom: {
            regex: "^I[A-Z]",
            match: false,
          },
        },
        {
          selector: "typeAlias",
          format: ["PascalCase"],
        },
        {
          selector: "class",
          format: ["PascalCase"],
        },
      ],

      // Prevent floating promises
      "@typescript-eslint/no-floating-promises": "error",

      // Require await in async functions
      "@typescript-eslint/require-await": "warn",
    },
  },
  {
    // `async ({}, use) => {}` is the canonical Playwright form for a fixture with no
    // dependencies, so the empty pattern is intentional in fixtures and specs.
    files: ["fixtures/**/*.ts", "tests/**/*.ts"],
    rules: { "no-empty-pattern": "off" },
  },
  {
    // Typed rules cannot run on plain JavaScript: there is no type information for it.
    files: ["**/*.{js,mjs,cjs}"],
    rules: {
      "@typescript-eslint/no-floating-promises": "off",
      "@typescript-eslint/require-await": "off",
    },
  },
  {
    // Ignore patterns
    ignores: [
      "node_modules/**",
      "dist/**",
      "playwright-report/**",
      "test-results/**",
      "*.config.ts",
      "*.config.js",
    ],
  },
]);

