1	#!/usr/bin/env node
2	/**
3	 * Enforces the project rules that can be checked statically.
4	 *
5	 * A rule that a script can verify should be a check, not a paragraph: it costs no
6	 * context tokens, it fires every time, and it cannot be talked out of its verdict.
7	 * Each check below names the rule file it enforces.
8	 *
9	 * Existing violations are recorded in .rules-lint-baseline.json and do not fail the
10	 * run — the baseline is a ratchet. A new violation, or more violations in an already
11	 * listed file, fails. Fewer violations pass and suggest refreshing the baseline.
12	 *
13	 * Usage:
14	 *   npm run rules:lint
15	 *   npm run rules:lint -- --update-baseline
16	 */
17	import { readFileSync, writeFileSync, existsSync } from 'node:fs';
18	import { execFileSync } from 'node:child_process';
19	
20	const BASELINE = '.rules-lint-baseline.json';
21	const updating = process.argv.includes('--update-baseline');
22	
23	// Tracked and new (untracked, not ignored) files: a new spec is checked before its first commit.
24	const files = execFileSync('git', ['ls-files', '--cached', '--others', '--exclude-standard', '*.ts'], { encoding: 'utf8' })
25	  .split('\n')
26	  .filter(Boolean);
27	
28	const read = (f) => {
29	  try {
30	    return readFileSync(f, 'utf8');
31	  } catch {
32	    return '';
33	  }
34	};
35	
36	const under = (f, ...prefixes) => prefixes.some((p) => f.startsWith(p));
37	
38	/**
39	 * Each check returns a Map of file -> number (violation count, or a size for pom-size).
40	 * `rule` points at the rule file in .claude/rules/ that states the invariant in prose.
41	 */
42	const CHECKS = [
43	  {
44	    id: 'no-expect-in-regression-specs',
45	    rule: 'playwright-specs-no-expect.md',
46	    hint: 'move the assertion into a should* method on the POM or a helper',
47	    run: () => {
48	      const out = new Map();
49	      for (const f of files) {
50	        if (!under(f, 'tests/specs/regression/') || !f.endsWith('.spec.ts')) continue;
51	        const n = (read(f).match(/\bexpect\s*\(/g) ?? []).length;
52	        if (n) out.set(f, n);
53	      }
54	      return out;
55	    },
56	  },
57	  {
58	    id: 'no-hardcoded-waits',
59	    rule: 'no-hardcoded-waits.md',
60	    hint: 'use a locator wait, toPass(), or a should* method instead',
61	    run: () => {
62	      const out = new Map();
63	      const re = /waitForTimeout\s*\(|this\.wait\s*\(|waitUntil:\s*['"]networkidle['"]/g;
64	      for (const f of files) {
65	        if (!under(f, 'page-objects/', 'tests/', 'utils/')) continue;
66	        const n = (read(f).match(re) ?? []).length;
67	        if (n) out.set(f, n);
68	      }
69	      return out;
70	    },
71	  },
72	  {
73	    id: 'pom-size',
74	    rule: 'page-object-size.md',
75	    hint: 'split the page object into components under components/',
76	    limit: 300,
77	    run: () => {
78	      const out = new Map();
79	      for (const f of files) {
80	        if (!under(f, 'page-objects/')) continue;
81	        const lines = read(f).split('\n').length;
82	        if (lines > 300) out.set(f, lines);
83	      }
84	      return out;
85	    },
86	  },
87	  {
88	    id: 'no-tc-ids-in-names',
89	    rule: 'test-naming-no-tc-ids.md',
90	    hint: "link the case with the annotation { type: 'test-case', description: 'TC-NN' } instead of naming it",
91	    run: () => {
92	      const out = new Map();
93	      const inTitle = /\b(?:test|describe)\s*\(\s*[`'"][^`'"]*\bTC-\d+/gi;
94	      for (const f of files) {
95	        if (!under(f, 'tests/')) continue;
96	        let n = /(^|\/)tc-\d+/i.test(f) ? 1 : 0;
97	        n += (read(f).match(inTitle) ?? []).length;
98	        if (n) out.set(f, n);
99	      }
100	      return out;
101	    },
102	  },
103	  {
104	    id: 'no-relative-imports',
105	    rule: 'api-test.md',
106	    hint: "use the @/ path alias",
107	    run: () => {
108	      const out = new Map();
109	      for (const f of files) {
110	        if (!under(f, 'tests/', 'page-objects/')) continue;
111	        const n = (read(f).match(/from\s+['"]\.\.\//g) ?? []).length;
112	        if (n) out.set(f, n);
113	      }
114	      return out;
115	    },
116	  },
117	  {
118	    id: 'no-hardcoded-endpoints',
119	    rule: 'api-test.md',
120	    hint: 'use a constant from utils/constants/routes.ts',
121	    run: () => {
122	      const out = new Map();
123	      for (const f of files) {
124	        if (!under(f, 'tests/')) continue;
125	        const n = (read(f).match(/['"`]\/(api|rest)\//g) ?? []).length;
126	        if (n) out.set(f, n);
127	      }
128	      return out;
129	    },
130	  },
131	  {
132	    id: 'seconds-to-ms-max-30',
133	    rule: 'date-helper-seconds-to-ms.md',
134	    hint: 'DateHelper.secondsToMs(n) — n must be ≤ 30; use minutesToMs for longer waits',
135	    run: () => {
136	      const out = new Map();
137	      const re = /secondsToMs\(\s*(\d+)\s*\)/g;
138	      for (const f of files) {
139	        if (f === 'utils/helpers/date-helper.ts') continue;
140	        const text = read(f);
141	        let n = 0;
142	        for (const match of text.matchAll(re)) {
143	          if (Number(match[1]) > 30) n += 1;
144	        }
145	        if (n) out.set(f, n);
146	      }
147	      return out;
148	    },
149	  },
150	];
151	
152	const results = new Map(CHECKS.map((c) => [c.id, c.run()]));
153	
154	if (updating) {
155	  const baseline = {};
156	  for (const [id, hits] of results) {
157	    if (hits.size) baseline[id] = Object.fromEntries([...hits].sort());
158	  }
159	  writeFileSync(BASELINE, `${JSON.stringify(baseline, null, 2)}\n`);
160	  const total = [...results.values()].reduce((a, m) => a + m.size, 0);
161	  console.log(`Baseline written to ${BASELINE}: ${total} file(s) recorded.`);
162	  process.exit(0);
163	}
164	
165	const baseline = existsSync(BASELINE) ? JSON.parse(readFileSync(BASELINE, 'utf8')) : {};
166	let failures = 0;
167	let improved = 0;
168	
169	for (const check of CHECKS) {
170	  const hits = results.get(check.id);
171	  const known = baseline[check.id] ?? {};
172	  const isNew = [];
173	  const worse = [];
174	
175	  for (const [file, count] of hits) {
176	    const before = known[file];
177	    if (before === undefined) isNew.push([file, count]);
178	    else if (count > before) worse.push([file, count, before]);
179	  }
180	  for (const [file, before] of Object.entries(known)) {
181	    const now = hits.get(file);
182	    if (now === undefined || now < before) improved += 1;
183	  }
184	
185	  const bad = isNew.length + worse.length;
186	  failures += bad;
187	  const label = check.limit ? `${check.id} (limit ${check.limit})` : check.id;
188	  console.log(
189	    `${bad ? '✗' : '✓'} ${label.padEnd(34)} ${String(hits.size).padStart(3)} file(s), ` +
190	      `${Object.keys(known).length} in baseline`,
191	  );
192	  for (const [file, count] of isNew) console.log(`    NEW    ${file} (${count})`);
193	  for (const [file, count, before] of worse) console.log(`    WORSE  ${file} (${before} → ${count})`);
194	  if (bad) console.log(`    rule: ${check.rule} — ${check.hint}`);
195	}
196	
197	if (improved) {
198	  console.log(`\n${improved} baseline entr(ies) improved. Refresh with: npm run rules:lint -- --update-baseline`);
199	}
200	console.log(failures === 0 ? '\nNo new rule violations.' : `\nNew rule violations: ${failures}`);
201	process.exit(failures === 0 ? 0 : 1);
202

