import z85 from 'z85';

// The shop reads the month of a coupon in capital letters, for example OCT.
const COUPON_MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
const COUPON_YEAR_DIGITS = 2;
const COUPON_PERCENT_DIGITS = 2;

// The coupon code is the Z85 encoding of `<MMM><YY>-<NN>` (test-cases/README.md).
const buildCouponCode = (monthsFromNow: number, percent: number, now: Date): string => {
  const date = new Date(now.getFullYear(), now.getMonth() + monthsFromNow, 1);
  const month = COUPON_MONTHS[date.getMonth()];
  const year = String(date.getFullYear()).slice(-COUPON_YEAR_DIGITS);
  const discount = String(percent).padStart(COUPON_PERCENT_DIGITS, '0');
  return z85.encode(`${month}${year}-${discount}`);
};

// Coupon of the current month, for the server's local time.
export const currentMonthCoupon = (percent: number, now: Date = new Date()): string =>
  buildCouponCode(0, percent, now);

// Coupon of the previous month: the server rejects it as expired.
export const previousMonthCoupon = (percent: number, now: Date = new Date()): string =>
  buildCouponCode(-1, percent, now);

