import type { ApiClient } from '@/core/api/api-client';
import { API_ROUTES } from '@/utils/constants/routes';
import type { DataResponse, ProductSearchItem } from '@/utils/types/api-responses';
import type { Customer } from '@/utils/types/customer';

interface ProductSearchResponse {
  data: ProductSearchItem[];
}

export class BasketApi {
  constructor(private readonly client: ApiClient) {}

  // Finds a catalog product by its exact name. The search returns partial matches, so the name is compared in full.
  async findProductId(productName: string): Promise<number> {
    const response = await this.client.get<ProductSearchResponse>(
      `${API_ROUTES.productSearch}?q=${encodeURIComponent(productName)}`,
    );
    const product = response.data.find((item) => item.name === productName);
    if (!product) {
      throw new Error(`Product "${productName}" is not in the catalog`);
    }
    return product.id;
  }

  async addProduct(customer: Customer, productName: string, quantity: number): Promise<void> {
    const productId = await this.findProductId(productName);
    await this.client.post<DataResponse<unknown>>(
      API_ROUTES.basketItems,
      { ProductId: productId, BasketId: customer.basketId, quantity },
      customer.token,
    );
  }
}

