import type { ApiClient } from '@/core/api/api-client';
import { API_ROUTES } from '@/utils/constants/routes';
import type { DataResponse, WalletBalanceResponse } from '@/utils/types/api-responses';
import type { Customer, SavedAddress, SavedCard } from '@/utils/types/customer';

interface CreatedItemResponse {
  id: number;
}

export class PaymentApi {
  constructor(private readonly client: ApiClient) {}

  async addSavedAddress(customer: Customer, address: SavedAddress): Promise<number> {
    const response = await this.client.post<DataResponse<CreatedItemResponse>>(
      API_ROUTES.addresses,
      address,
      customer.token,
    );
    return response.data.id;
  }

  async addSavedCard(customer: Customer, card: SavedCard): Promise<number> {
    const response = await this.client.post<DataResponse<CreatedItemResponse>>(API_ROUTES.cards, card, customer.token);
    return response.data.id;
  }

  // The shop adds money to the wallet only with a saved card, so the card id is the payment id.
  async topUpWallet(customer: Customer, cardId: number, amount: number): Promise<void> {
    await this.client.put(API_ROUTES.walletBalance, { balance: amount, paymentId: cardId }, customer.token);
  }

  async getWalletBalance(customer: Customer): Promise<number> {
    const response = await this.client.get<WalletBalanceResponse>(API_ROUTES.walletBalance, customer.token);
    return response.data;
  }
}

