import type { Page } from '@playwright/test';
import { expectContainText, expectCount, expectText, expectVisible } from '@/utils/assertions/ui-assertions';

// The top bar: the account menu, the basket button with its counter and the Orders & Payment submenu.
export class NavbarComponent {
  private readonly accountButton;
  private readonly basketButton;
  private readonly basketCounter;
  private readonly menu;

  constructor(private readonly page: Page) {
    this.accountButton = page.getByRole('button', { name: 'Show/hide account menu' });
    this.basketButton = page.getByRole('button', { name: 'Show the shopping cart' });
    this.basketCounter = this.basketButton.locator('#itemTotal');
    this.menu = page.getByRole('menu');
  }

  async clickAccount(): Promise<void> {
    await this.accountButton.click();
  }

  async clickMenuItem(name: string): Promise<void> {
    await this.menu.getByRole('menuitem', { name, exact: true }).click();
  }

  async clickOpenBasket(): Promise<void> {
    await this.basketButton.click();
  }

  async shouldSeeBasketCounter(count: number): Promise<void> {
    await expectText(this.basketCounter, String(count), `Basket counter shows ${count}`);
  }

  async shouldSeeAccountMenuItem(name: string): Promise<void> {
    await expectVisible(this.menu.getByRole('menuitem', { name, exact: true }), `Account menu shows the item "${name}"`);
  }

  async shouldSeeAccountMenuEmail(email: string): Promise<void> {
    await expectContainText(this.menu, email, `Account menu shows the email ${email}`);
  }

  async shouldNotSeeAccountMenuEmail(email: string): Promise<void> {
    await expectCount(this.menu.filter({ hasText: email }), 0, `Account menu does not show the email ${email}`);
  }

  async shouldSeeAccountMenuItemCount(name: string, count: number): Promise<void> {
    await expectCount(
      this.menu.getByRole('menuitem', { name, exact: true }),
      count,
      `Account menu shows the item "${name}" ${count} time(s)`,
    );
  }
}

