    const host = new URL(this.page.url() === 'about:blank' ? UI_ROUTES.login : this.page.url(), 'http://localhost').hostname;
    await this.page.context().addCookies([{ name: SESSION_TOKEN_KEY, value: customer.token, domain: host, path: '/' }]);
