import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectContainText, expectCount, expectUrlMatches, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTES } from '@/utils/constants/ui-routes';
import type { ProductInfo } from '@/utils/types/product';

const ADD_TO_BASKET_BUTTON = 'Add to Basket';

export class SearchPage extends BasePage {
  private readonly productTiles: Locator;

  constructor(page: Page) {
    super(page);
    this.productTiles = page.locator('mat-grid-tile');
  }

  async open(): Promise<void> {
    await this.page.goto(UI_ROUTES.search);
    await this.shouldSeePage();
  }

  async clickAddToBasket(product: ProductInfo): Promise<void> {
    await this.productTile(product).getByRole('button', { name: ADD_TO_BASKET_BUTTON }).click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrlMatches(this.page, /#\/search/, 'The product list is open');
    await expectVisible(this.productTiles.first(), 'The product list shows products');
  }

  async shouldSeeProduct(product: ProductInfo): Promise<void> {
    const tile = this.productTile(product);
    await expectContainText(tile, product.price, `Product "${product.name}" shows the price ${product.price}`);
    await expectVisible(
      tile.getByRole('button', { name: ADD_TO_BASKET_BUTTON }),
      `Product "${product.name}" shows the button "${ADD_TO_BASKET_BUTTON}"`,
    );
  }

  async shouldSeeAddToBasketButtonCount(product: ProductInfo, count: number): Promise<void> {
    await expectCount(
      this.productTile(product).getByRole('button', { name: ADD_TO_BASKET_BUTTON }),
      count,
      `Product "${product.name}" has ${count} "${ADD_TO_BASKET_BUTTON}" button(s)`,
    );
  }

  private productTile(product: ProductInfo): Locator {
    return this.productTiles.filter({ hasText: product.name });
  }
}

