import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import {
  expectCount,
  expectContainText,
  expectDisabled,
  expectHidden,
  expectText,
  expectUrlMatches,
  expectVisible,
} from '@/utils/assertions/ui-assertions';
import { UI_ROUTES } from '@/utils/constants/ui-routes';
import type { ProductInfo } from '@/utils/types/product';

const CHECKOUT_BUTTON = 'Checkout';
const TOTAL_PRICE_PREFIX = 'Total Price:';
const INCREASE_BUTTON = 'Increase the quantity of one item';
const DECREASE_BUTTON = 'Decrease the quantity of one item';
const REMOVE_BUTTON = 'Remove the product from the basket';

export class BasketPage extends BasePage {
  private readonly rows: Locator;
  private readonly totalPrice: Locator;
  private readonly checkoutButton: Locator;

  constructor(page: Page) {
    super(page);
    this.rows = page.getByRole('row').filter({ has: page.getByRole('cell') });
    this.totalPrice = page.getByText(TOTAL_PRICE_PREFIX);
    this.checkoutButton = page.getByRole('button', { name: CHECKOUT_BUTTON });
  }

  async open(): Promise<void> {
    await this.page.goto(UI_ROUTES.basket);
    await this.shouldSeePage();
  }

  async clickIncreaseQuantity(product: ProductInfo): Promise<void> {
    await this.productRow(product).getByRole('button', { name: INCREASE_BUTTON }).click();
  }

  async clickDecreaseQuantity(product: ProductInfo): Promise<void> {
    await this.productRow(product).getByRole('button', { name: DECREASE_BUTTON }).click();
  }

  async clickRemove(product: ProductInfo): Promise<void> {
    await this.productRow(product).getByRole('button', { name: REMOVE_BUTTON }).click();
  }

  async clickCheckout(): Promise<void> {
    await this.checkoutButton.click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrlMatches(this.page, /#\/basket$/, 'The basket page is open');
  }

  async shouldSeeProductRow(product: ProductInfo, quantity: number): Promise<void> {
    const row = this.productRow(product);
    await expectVisible(row, `Basket shows the row of "${product.name}"`);
    await expectContainText(row, product.price, `Row of "${product.name}" shows the price ${product.price}`);
    await expectText(
      row.getByTestId('basket-quantity'),
      String(quantity),
      `Row of "${product.name}" shows the quantity ${quantity}`,
    );
  }

  async shouldNotSeeProductRow(product: ProductInfo): Promise<void> {
    await expectHidden(this.productRow(product), `Basket has no row of "${product.name}"`);
  }

  async shouldSeeRowCount(count: number): Promise<void> {
    await expectCount(this.rows, count, `Basket has ${count} product row(s)`);
  }

  async shouldSeeTotalPrice(price: string): Promise<void> {
    await expectContainText(this.totalPrice, `${TOTAL_PRICE_PREFIX} ${price}`, `Basket shows the total ${price}`);
  }

  async shouldSeeCheckoutEnabled(): Promise<void> {
    await expectVisible(this.checkoutButton, 'Basket shows the button "Checkout"');
  }

  async shouldSeeCheckoutDisabled(): Promise<void> {
    await expectDisabled(this.checkoutButton, 'Checkout button is disabled');
  }

  private productRow(product: ProductInfo): Locator {
    return this.rows.filter({ hasText: product.name });
  }
}

