await (async (page) => {
  const base = 'http://localhost:3000';
  const email = `probe3-${Date.now()}@example.test`;
  const password = 'Passw0rd!probe3';
  await page.request.post(base + '/api/Users', { data: { email, password, passwordRepeat: password } });
  const login = await (await page.request.post(base + '/rest/user/login', { data: { email, password } })).json();
  const { token, bid } = login.authentication;
  const ctx = page.context();
  await ctx.addCookies([{ name: 'token', value: token, domain: 'localhost', path: '/' }, { name: 'cookieconsent_status', value: 'dismiss', domain: 'localhost', path: '/' }, { name: 'language', value: 'en', domain: 'localhost', path: '/' }]);
  await ctx.addInitScript(([t, b]) => { localStorage.setItem('token', t); sessionStorage.setItem('bid', String(b)); }, [token, bid]);
  await page.goto(base + '/#/search');
  await page.waitForTimeout(2500);
  const info = await page.evaluate(() => {
    const el = [...document.querySelectorAll('*')].find((e) => e.children.length === 0 && e.textContent.trim() === 'Eggfruit Juice (500ml)');
    if (!el) return 'not found';
    let card = el;
    for (let i = 0; i < 8 && card.parentElement; i++) {
      card = card.parentElement;
      if (card.querySelector('button') && /Add to Basket/i.test(card.innerText) && card.innerText.length < 400) break;
    }
    return { tagPath: card.tagName + '.' + card.className, text: card.innerText, html: card.outerHTML.slice(0, 1800) };
  });
  const cardCount = await page.evaluate(() => document.querySelectorAll('.mat-mdc-card, mat-card, .mat-card').length);
  return { cardCount, info };
})(page);
