async (page) => {
  const base = 'http://localhost:3000';
  const email = `probe4-${Date.now()}@example.test`;
  const password = 'Passw0rd!probe4';
  await page.request.post(base + '/api/Users', { data: { email, password, passwordRepeat: password } });
  const login = await (await page.request.post(base + '/rest/user/login', { data: { email, password } })).json();
  const { token, bid } = login.authentication;
  const auth = { Authorization: 'Bearer ' + token };
  const pid = (await (await page.request.get(base + '/rest/products/search?q=Eggfruit')).json()).data.find((p) => p.name === 'Eggfruit Juice (500ml)').id;
  await page.request.post(base + '/api/BasketItems', { data: { ProductId: pid, BasketId: bid, quantity: 2 }, headers: auth });
  const addr = await page.request.post(base + '/api/Addresss', { data: { fullName: 'Test Customer', mobileNum: 501234567, zipCode: '01001', streetAddress: '1 Khreshchatyk Street', city: 'Kyiv', state: 'Kyiv', country: 'Ukraine' }, headers: auth });
  const card = await page.request.post(base + '/api/Cards', { data: { fullName: 'Test Customer', cardNum: 4111111111111111, expMonth: 12, expYear: 2090 }, headers: auth });
  const cardId = (await card.json()).data.id;
  const topup = await page.request.put(base + '/rest/wallet/balance', { data: { balance: 5, paymentId: cardId }, headers: auth });
  const ctx = page.context();
  await ctx.addCookies([{ name: 'token', value: token, domain: 'localhost', path: '/' }, { name: 'cookieconsent_status', value: 'dismiss', domain: 'localhost', path: '/' }, { name: 'language', value: 'en', domain: 'localhost', path: '/' }]);
  await ctx.addInitScript(([t, b]) => { localStorage.setItem('token', t); sessionStorage.setItem('bid', String(b)); }, [token, bid]);
  const out = { addr: addr.status(), card: card.status(), topup: topup.status() };
  await page.goto(base + '/#/basket');
  await page.waitForTimeout(1500);
  out.basketTitle = await page.locator('h1').first().textContent();
  await page.getByRole('button', { name: 'Checkout' }).click();
  await page.waitForTimeout(1500);
  out.addressPage = await page.locator('body').ariaSnapshot();
  return out;
}

