import type { Page } from '@playwright/test';
import { expectCount, expectText, expectVisible } from '@/utils/assertions/ui-assertions';

const ACCOUNT_BUTTON = 'Show/hide account menu';
const BASKET_BUTTON = 'Show the shopping cart';
const ORDERS_AND_PAYMENT_ITEM = 'Show Orders and Payment Menu';
const ORDER_HISTORY_ITEM = 'Go to order history page';
const DIGITAL_WALLET_ITEM = 'Go to wallet page';

// The top bar: the account menu with its submenus, and the basket button with its counter.
export class NavbarComponent {
  private readonly basketCounter;

  constructor(private readonly page: Page) {
    this.basketCounter = page.getByRole('button', { name: BASKET_BUTTON }).getByText(/^\d+$/);
  }

  async clickOpenBasket(): Promise<void> {
    await this.page.getByRole('button', { name: BASKET_BUTTON }).click();
  }

  async openOrderHistory(): Promise<void> {
    await this.clickAccountMenuPath([ORDERS_AND_PAYMENT_ITEM, ORDER_HISTORY_ITEM]);
  }

  async openDigitalWallet(): Promise<void> {
    await this.clickAccountMenuPath([ORDERS_AND_PAYMENT_ITEM, DIGITAL_WALLET_ITEM]);
  }

  async closeAccountMenu(): Promise<void> {
    await this.page.keyboard.press('Escape');
  }

  async shouldSeeBasketCounter(count: number): Promise<void> {
    await expectText(this.basketCounter, String(count), `Basket counter shows ${count}`);
  }

  async shouldSeeAccountMenuItem(name: string): Promise<void> {
    await expectVisible(this.accountMenuItem(name), `Account menu shows the item "${name}"`);
  }

  async shouldSeeAccountMenuEmail(email: string): Promise<void> {
    await expectVisible(this.accountMenu().getByText(email), `Account menu shows the email ${email}`);
  }

  async shouldNotSeeAccountMenuEmail(email: string): Promise<void> {
    await expectCount(this.accountMenu().getByText(email), 0, `Account menu does not show the email ${email}`);
  }

  // Opens the account menu, then each submenu in turn. Each step waits for its item to be visible.
  private async clickAccountMenuPath(itemNames: string[]): Promise<void> {
    await this.page.getByRole('button', { name: ACCOUNT_BUTTON }).click();
    for (const name of itemNames) {
      await this.accountMenuItem(name).click();
    }
  }

  private accountMenu() {
    return this.page.getByRole('menu');
  }

  private accountMenuItem(name: string) {
    return this.page.getByRole('menuitem', { name, exact: true });
  }
}

