import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectCount, expectText, expectUrlMatches, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTES } from '@/utils/constants/ui-routes';
import type { ProductInfo } from '@/utils/types/product';

const ADD_TO_BASKET_BUTTON = 'Add to Basket';

export class SearchPage extends BasePage {
  private readonly productCards: Locator;

  constructor(page: Page) {
    super(page);
    this.productCards = page.locator('article.product');
  }

  async open(): Promise<void> {
    await this.page.goto(UI_ROUTES.search);
    await this.shouldSeePage();
  }

  async clickAddToBasket(product: ProductInfo): Promise<void> {
    await this.productCard(product).getByRole('button', { name: ADD_TO_BASKET_BUTTON }).click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrlMatches(this.page, /#\/search/, 'The product list is open');
    await expectVisible(this.productCards.first(), 'The product list shows products');
  }

  async shouldSeeProduct(product: ProductInfo): Promise<void> {
    const card = this.productCard(product);
    await expectVisible(card, `The product list shows "${product.name}"`);
    await expectText(card.locator('.price'), product.price, `"${product.name}" shows the price ${product.price}`);
    await expectVisible(
      card.getByRole('button', { name: ADD_TO_BASKET_BUTTON }),
      `"${product.name}" shows the button "${ADD_TO_BASKET_BUTTON}"`,
    );
  }

  async shouldSeeProductCount(count: number): Promise<void> {
    await expectCount(this.productCards, count, `The product list shows ${count} products`);
  }

  private productCard(product: ProductInfo): Locator {
    return this.productCards.filter({ hasText: product.name });
  }
}

