import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { CHECKOUT_BUTTON_TEXT } from '@/page-objects/checkout/checkout-button';
import { expectText, expectUrlMatches, expectVisible } from '@/utils/assertions/ui-assertions';
import type { OrderTotals } from '@/utils/types/order';

const SUMMARY_TITLE = 'Order Summary';

// Summary before the order is placed. Each line is a row: label, then value.
export class OrderSummaryPage extends BasePage {
  constructor(page: Page) {
    super(page);
  }

  async clickPlaceOrder(): Promise<void> {
    await this.page.locator('button', { hasText: CHECKOUT_BUTTON_TEXT.placeOrder }).click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrlMatches(this.page, /#\/order-summary$/, 'The order summary page is open');
    await expectVisible(this.page.getByText(SUMMARY_TITLE, { exact: true }), `The page shows "${SUMMARY_TITLE}"`);
  }

  async shouldSeeDeliveryAddress(streetAddress: string): Promise<void> {
    await expectVisible(this.page.getByText(streetAddress), `The summary shows the address ${streetAddress}`);
  }

  async shouldSeePaymentMethod(method: string): Promise<void> {
    await expectVisible(this.page.getByText(method), `The summary shows the payment method "${method}"`);
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    await expectText(this.totalValue('Items'), totals.items, `Items show ${totals.items}`);
    await expectText(this.totalValue('Delivery'), totals.delivery, `Delivery shows ${totals.delivery}`);
    await expectText(this.totalValue('Promotion'), totals.promotion, `Promotion shows ${totals.promotion}`);
    await expectText(this.totalValue('Total Price'), totals.total, `Total Price shows ${totals.total}`);
  }

  private totalValue(label: string): Locator {
    return this.page
      .getByRole('row')
      .filter({ has: this.page.getByRole('cell', { name: label, exact: true }) })
      .getByRole('cell')
      .last();
  }
}

