import type { PagesFixtures } from '@/fixtures/pages.fixture';
import type { DeliveryOption } from '@/page-objects/checkout/delivery-speed-page';
import { SAVED_ADDRESS } from '@/utils/helpers/customer-data';

// Flows that several test cases repeat: the basket to the checkout steps.
// The helpers only act and call should* checks of the page objects.
export type CheckoutPages = Pick<
  PagesFixtures,
  'basketPage' | 'addressSelectionPage' | 'deliverySpeedPage' | 'paymentPage'
>;

// Basket → Checkout → saved address → Continue. Ends on "Choose a delivery speed".
export const openDeliverySpeedStep = async (pages: CheckoutPages): Promise<void> => {
  await pages.basketPage.open();
  await pages.basketPage.clickCheckout();
  await pages.addressSelectionPage.selectAddress(SAVED_ADDRESS);
  await pages.addressSelectionPage.clickContinue();
  await pages.deliverySpeedPage.shouldSeePage();
};

// Chooses the delivery method and continues. Ends on "My Payment Options".
export const chooseDeliveryAndOpenPayment = async (pages: CheckoutPages, option: DeliveryOption): Promise<void> => {
  await pages.deliverySpeedPage.selectDelivery(option);
  await pages.deliverySpeedPage.clickContinue();
  await pages.paymentPage.shouldSeePage();
};

