import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS } from '@/utils/constants/products';
import { SHOP_MESSAGES } from '@/utils/constants/shop-messages';

test('Add a product to the basket', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-02' },
}, async ({ customer, loginPage, searchPage, navbar, snackBar, basketPage }) => {
  await test.step('Precondition: log in the new customer with an empty basket', async () => {
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the product list', async () => {
    await searchPage.open();
    await searchPage.shouldSeeProduct(PRODUCTS.eggfruit);
    await navbar.shouldSeeBasketCounter(0);
  });

  await test.step('2. Click Add to Basket on the product', async () => {
    await searchPage.clickAddToBasket(PRODUCTS.eggfruit);
    await snackBar.shouldSeeMessage(SHOP_MESSAGES.addedToBasket(PRODUCTS.eggfruit.name));
    await navbar.shouldSeeBasketCounter(1);
  });

  await test.step('3. Open the basket', async () => {
    await navbar.clickOpenBasket();
    await basketPage.shouldSeePage();
    await basketPage.shouldSeeRowCount(1);
    await basketPage.shouldSeeProductRow(PRODUCTS.eggfruit, 1);
  });

  await test.step('4. Read the total of the basket', async () => {
    await basketPage.shouldSeeTotalPrice(PRODUCTS.eggfruit.price);
  });
});

