import { test } from '@/fixtures/customer.fixture';
import { addProductsToBasket, addSavedAddressAndCard } from '@/tests/helpers/customer-setup';
import { chooseDeliveryAndOpenPayment, openDeliverySpeedStep } from '@/tests/helpers/checkout-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { COUPON_PERCENT, DELIVERY_OPTIONS } from '@/utils/constants/delivery';
import { PRODUCTS } from '@/utils/constants/products';
import { ORDER_TOTALS } from '@/utils/constants/order-totals';
import { SAVED_ADDRESS, SAVED_CARD } from '@/utils/helpers/customer-data';
import { currentMonthCoupon } from '@/utils/helpers/coupon-helper';

const EGGFRUIT_QUANTITY = 2;

test('Valid coupon on the payment step', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.coupon],
  annotation: { type: 'test-case', description: 'TC-05' },
}, async ({ api, customer, loginPage, basketPage, addressSelectionPage, deliverySpeedPage, paymentPage, orderSummaryPage }) => {
  await test.step('Precondition: set up the saved address, the saved card and the basket, then log in', async () => {
    await addSavedAddressAndCard(api, customer);
    await addProductsToBasket(api, customer, [{ product: PRODUCTS.eggfruit, quantity: EGGFRUIT_QUANTITY }]);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the basket and click Checkout', async () => {
    await basketPage.open();
    await basketPage.clickCheckout();
    await addressSelectionPage.shouldSeePage();
    await addressSelectionPage.shouldSeeSavedAddress(SAVED_ADDRESS);
  });

  await test.step('2. Select the saved address and click Continue', async () => {
    await addressSelectionPage.selectAddress(SAVED_ADDRESS);
    await addressSelectionPage.clickContinue();
    await deliverySpeedPage.shouldSeePage();
    await deliverySpeedPage.shouldSeeDeliveryOption(DELIVERY_OPTIONS.oneDay);
    await deliverySpeedPage.shouldSeeDeliveryOption(DELIVERY_OPTIONS.fast);
    await deliverySpeedPage.shouldSeeDeliveryOption(DELIVERY_OPTIONS.standard);
  });

  await test.step('3. Select One Day Delivery and click Continue', async () => {
    await deliverySpeedPage.selectDelivery(DELIVERY_OPTIONS.oneDay);
    await deliverySpeedPage.clickContinue();
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeSavedCard(SAVED_CARD);
    await paymentPage.shouldSeeCouponPanel();
  });

  await test.step('4. Open the coupon panel, type the coupon code and click Redeem', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.fillCoupon(currentMonthCoupon(COUPON_PERCENT));
    await paymentPage.clickRedeem();
    await paymentPage.shouldSeeDiscountApplied(COUPON_PERCENT);
  });

  await test.step('5. Select the saved card and click Continue', async () => {
    await paymentPage.selectSavedCard(SAVED_CARD);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeTotals(ORDER_TOTALS.eggfruitTwoWithCoupon);
  });
});

