import { test } from '@/fixtures/customer.fixture';
import { addProductsToBasket, addSavedAddressAndCard, topUpWallet } from '@/tests/helpers/customer-setup';
import { chooseDeliveryAndOpenPayment, openDeliverySpeedStep } from '@/tests/helpers/checkout-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { DELIVERY_OPTIONS } from '@/utils/constants/delivery';
import { PRODUCTS } from '@/utils/constants/products';
import { PAYMENT_METHOD_DIGITAL_WALLET, WALLET } from '@/utils/constants/wallet';
import { WALLET_ORDER_TOTAL } from '@/utils/constants/order-totals';

const EGGFRUIT_QUANTITY = 1;
const NO_ORDERS_YET = 0;
const ONE_ORDER = 1;

test('Payment with the wallet', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.wallet],
  annotation: { type: 'test-case', description: 'TC-08' },
}, async ({ api, customer, loginPage, navbar, basketPage, addressSelectionPage, deliverySpeedPage, paymentPage, orderSummaryPage, orderCompletionPage, orderHistoryPage, digitalWalletPage }) => {
  const pages = { basketPage, addressSelectionPage, deliverySpeedPage, paymentPage };
  let orderId = '';

  await test.step('Precondition: set up the saved address and the saved card, put one product into the basket, top up the wallet, then log in', async () => {
    const cardId = await addSavedAddressAndCard(api, customer);
    await addProductsToBasket(api, customer, [{ product: PRODUCTS.eggfruit, quantity: EGGFRUIT_QUANTITY }]);
    await topUpWallet(api, customer, cardId, WALLET.firstTopUp);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the basket, click Checkout, select the saved address and click Continue', async () => {
    await openDeliverySpeedStep(pages);
  });

  await test.step('2. Select Standard Delivery and click Continue', async () => {
    await deliverySpeedPage.selectDelivery(DELIVERY_OPTIONS.standard);
    await deliverySpeedPage.clickContinue();
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeWalletBalance(WALLET.firstBalance);
  });

  await test.step('3. Read the button Pay 8.99¤', async () => {
    await paymentPage.shouldSeeWalletPayDisabled(WALLET_ORDER_TOTAL);
  });

  await test.step('4. Open the order history', async () => {
    await navbar.openOrderHistory();
    await orderHistoryPage.shouldSeeNoOrders();
  });

  await test.step('5. Open the digital wallet', async () => {
    await navbar.openDigitalWallet();
    await digitalWalletPage.shouldSeeBalance(WALLET.firstBalance);
  });

  await test.step('Precondition: top up the wallet with the saved card so that the balance equals the order total', async () => {
    const cardId = await api.payment.getWalletCardId(customer);
    await topUpWallet(api, customer, cardId, WALLET.secondTopUp);
  });

  await test.step('6. Open the basket, click Checkout, select the saved address, select Standard Delivery and click Continue', async () => {
    await chooseDeliveryAndOpenPayment(pages, DELIVERY_OPTIONS.standard, { openDeliverySpeedFirst: true });
    await paymentPage.shouldSeeWalletBalance(WALLET.balanceBeforeOrder);
    await paymentPage.shouldSeeWalletPayEnabled(WALLET_ORDER_TOTAL);
  });

  await test.step('7. Click Pay 8.99¤', async () => {
    await paymentPage.clickWalletPay(WALLET_ORDER_TOTAL);
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeePaymentMethod(PAYMENT_METHOD_DIGITAL_WALLET);
    await orderSummaryPage.shouldSeeTotalPrice(WALLET_ORDER_TOTAL);
  });

  await test.step('8. Click Place your order and pay', async () => {
    await orderSummaryPage.clickPlaceOrder();
    await orderCompletionPage.shouldSeePage();
    orderId = orderCompletionPage.getOrderId();
  });

  await test.step('9. Open the digital wallet', async () => {
    await navbar.openDigitalWallet();
    await digitalWalletPage.shouldSeeBalance(WALLET.balanceAfterOrder);
  });

  await test.step('10. Open the order history', async () => {
    await navbar.openOrderHistory();
    await orderHistoryPage.shouldSeeOrderCount(ONE_ORDER);
    await orderHistoryPage.shouldSeeOrder(orderId, WALLET_ORDER_TOTAL);
    await orderHistoryPage.shouldSeeOrderBonus(orderId, WALLET.bonusPoints);
  });
});

