import type { APIRequestContext } from '@playwright/test';

const AUTHORIZATION_HEADER = 'Authorization';
const BEARER_PREFIX = 'Bearer';

// Thin JSON wrapper over Playwright's request context. A failed call throws, so setup never goes on silently.
export class ApiClient {
  constructor(private readonly request: APIRequestContext) {}

  async get<T>(path: string, token?: string): Promise<T> {
    const response = await this.request.get(path, { headers: this.headers(token) });
    return this.parse<T>('GET', path, response);
  }

  async post<T>(path: string, body: unknown, token?: string): Promise<T> {
    const response = await this.request.post(path, { data: body, headers: this.headers(token) });
    return this.parse<T>('POST', path, response);
  }

  async put<T>(path: string, body: unknown, token?: string): Promise<T> {
    const response = await this.request.put(path, { data: body, headers: this.headers(token) });
    return this.parse<T>('PUT', path, response);
  }

  private headers(token?: string): Record<string, string> {
    return token ? { [AUTHORIZATION_HEADER]: `${BEARER_PREFIX} ${token}` } : {};
  }

  private async parse<T>(method: string, path: string, response: { ok(): boolean; status(): number; text(): Promise<string> }): Promise<T> {
    if (!response.ok()) {
      throw new Error(`${method} ${path} failed with status ${response.status()}: ${await response.text()}`);
    }
    return (await response.json()) as T;
  }
}

