import { test } from '@/fixtures/customer.fixture';
import { addSavedAddressAndCard } from '@/tests/helpers/customer-setup';
import { chooseDeliveryAndOpenPayment } from '@/tests/helpers/checkout-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { COUPON_PERCENT, DELIVERY_OPTIONS } from '@/utils/constants/delivery';
import { ORDER_TOTALS } from '@/utils/constants/order-totals';
import { PRODUCTS } from '@/utils/constants/products';
import { cardPaymentMethod, SAVED_ADDRESS, SAVED_CARD } from '@/utils/helpers/customer-data';
import { currentMonthCoupon } from '@/utils/helpers/coupon-helper';

const EGGFRUIT_QUANTITY = 2;
const CARROT_QUANTITY = 1;
const BASKET_COUNT_AFTER_ADDING = EGGFRUIT_QUANTITY + CARROT_QUANTITY;
const EMPTY_BASKET_COUNT = 0;
const ONE_ORDER = 1;

test('Order with a card, from basket to order history', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.checkout],
  annotation: { type: 'test-case', description: 'TC-07' },
}, async ({ api, customer, loginPage, searchPage, navbar, basketPage, addressSelectionPage, deliverySpeedPage, paymentPage, orderSummaryPage, orderCompletionPage, orderHistoryPage }) => {
  let orderId = '';

  await test.step('Precondition: set up the saved address and the saved card, then log in', async () => {
    await addSavedAddressAndCard(api, customer);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the product list and add product A two times and product B one time', async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(PRODUCTS.eggfruit);
    await searchPage.clickAddToBasket(PRODUCTS.eggfruit);
    await searchPage.clickAddToBasket(PRODUCTS.carrot);
    await navbar.shouldSeeBasketCounter(BASKET_COUNT_AFTER_ADDING);
  });

  await test.step('2. Open the basket', async () => {
    await basketPage.open();
    await basketPage.shouldSeeProductRow(PRODUCTS.eggfruit, EGGFRUIT_QUANTITY);
    await basketPage.shouldSeeProductRow(PRODUCTS.carrot, CARROT_QUANTITY);
    await basketPage.shouldSeeTotalPrice('20.97¤');
  });

  await test.step('3. Click Checkout, select the saved address and click Continue', async () => {
    await basketPage.clickCheckout();
    await addressSelectionPage.selectAddress(SAVED_ADDRESS);
    await addressSelectionPage.clickContinue();
    await deliverySpeedPage.shouldSeePage();
  });

  await test.step('4. Select One Day Delivery and click Continue', async () => {
    await chooseDeliveryAndOpenPayment(
      { basketPage, addressSelectionPage, deliverySpeedPage, paymentPage },
      DELIVERY_OPTIONS.oneDay,
    );
  });

  await test.step('5. Open the coupon panel, type the coupon code and click Redeem', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.fillCoupon(currentMonthCoupon(COUPON_PERCENT));
    await paymentPage.clickRedeem();
    await paymentPage.shouldSeeDiscountApplied(COUPON_PERCENT);
  });

  await test.step('6. Select the saved card and click Continue', async () => {
    await paymentPage.selectSavedCard(SAVED_CARD);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeDeliveryAddress(SAVED_ADDRESS.streetAddress);
    await orderSummaryPage.shouldSeePaymentMethod(cardPaymentMethod(SAVED_CARD));
    await orderSummaryPage.shouldSeeTotals(ORDER_TOTALS.cardOrderWithCoupon);
  });

  await test.step('7. Click Place your order and pay', async () => {
    await orderSummaryPage.clickPlaceOrder();
    await orderCompletionPage.shouldSeePage();
    orderId = orderCompletionPage.getOrderId();
  });

  await test.step('8. Read the order summary on the confirmation page', async () => {
    await orderCompletionPage.shouldSeeProductLine(PRODUCTS.eggfruit, EGGFRUIT_QUANTITY);
    await orderCompletionPage.shouldSeeProductLine(PRODUCTS.carrot, CARROT_QUANTITY);
    await orderCompletionPage.shouldSeeTotals(ORDER_TOTALS.cardOrderWithCoupon);
  });

  await test.step('9. Read the basket counter and open the basket', async () => {
    await navbar.shouldSeeBasketCounter(EMPTY_BASKET_COUNT);
    await basketPage.open();
    await basketPage.shouldSeeRowCount(EMPTY_BASKET_COUNT);
    await basketPage.shouldSeeCheckoutDisabled();
  });

  await test.step('10. Open the order history', async () => {
    await navbar.openOrderHistory();
    await orderHistoryPage.shouldSeeOrderCount(ONE_ORDER);
    await orderHistoryPage.shouldSeeOrder(orderId, ORDER_TOTALS.cardOrderWithCoupon.total);
    await orderHistoryPage.shouldSeeOrderLine(orderId, PRODUCTS.eggfruit, EGGFRUIT_QUANTITY);
    await orderHistoryPage.shouldSeeOrderLine(orderId, PRODUCTS.carrot, CARROT_QUANTITY);
  });
});

