1	import { BasePage } from '@/page-objects/base-page';
2	import { expectDisabled, expectEnabled, expectUrlMatches, expectVisible } from '@/utils/assertions/ui-assertions';
3	import { UI_ROUTES } from '@/utils/constants/ui-routes';
4	import type { Customer } from '@/utils/types/customer';
5	import type { Page } from '@playwright/test';
6	
7	const LOGIN_TITLE = 'Login';
8	const INVALID_CREDENTIALS_MESSAGE = 'Invalid email or password.';
9	const SESSION_TOKEN_KEY = 'token';
10	const SESSION_BASKET_KEY = 'bid';
11	
12	export class LoginPage extends BasePage {
13	  private readonly title;
14	  private readonly emailField;
15	  private readonly passwordField;
16	  private readonly loginButton;
17	  private readonly errorMessage;
18	
19	  // appHost is the host of baseURL: the cookie domain of the session.
20	  constructor(page: Page, private readonly appHost: string) {
21	    super(page);
22	    this.title = page.getByRole('heading', { name: LOGIN_TITLE, exact: true });
23	    this.emailField = page.getByLabel('Text field for the login email');
24	    this.passwordField = page.getByLabel('Text field for the login password');
25	    this.loginButton = page.getByRole('button', { name: 'Login', exact: true });
26	    this.errorMessage = page.getByText(INVALID_CREDENTIALS_MESSAGE);
27	  }
28	
29	  async open(): Promise<void> {
30	    await this.page.goto(UI_ROUTES.login);
31	    await this.shouldSeePage();
32	  }
33	
34	  // A real UI login. Use it only when the login screen is under test (auth-and-sessions.md).
35	  async login(email: string, password: string): Promise<void> {
36	    await this.emailField.fill(email);
37	    await this.passwordField.fill(password);
38	    await this.loginButton.click();
39	  }
40	
41	  // Starts a logged-in session without the UI: the token, the basket id and the cookie go in before the app loads.
42	  async authenticate(customer: Customer): Promise<void> {
43	    await this.page.context().addCookies([{ name: SESSION_TOKEN_KEY, value: customer.token, domain: this.appHost, path: '/' }]);
44	    await this.page.context().addInitScript(
45	      ({ tokenKey, basketKey, token, basketId }) => {
46	        localStorage.setItem(tokenKey, token);
47	        sessionStorage.setItem(basketKey, String(basketId));
48	      },
49	      { tokenKey: SESSION_TOKEN_KEY, basketKey: SESSION_BASKET_KEY, token: customer.token, basketId: customer.basketId },
50	    );
51	    await this.page.goto(UI_ROUTES.search);
52	  }
53	
54	  async clickLogin(): Promise<void> {
55	    await this.loginButton.click();
56	  }
57	
58	  async shouldSeePage(): Promise<void> {
59	    await expectVisible(this.title, 'Login page shows the title "Login"');
60	    await expectVisible(this.emailField, 'Login page shows the field "Email"');
61	    await expectVisible(this.passwordField, 'Login page shows the field "Password"');
62	    await expectVisible(this.loginButton, 'Login page shows the button "Log in"');
63	  }
64	
65	  async shouldSeeInvalidCredentialsError(): Promise<void> {
66	    await expectVisible(this.errorMessage, `Login page shows the error "${INVALID_CREDENTIALS_MESSAGE}"`);
67	  }
68	
69	  async shouldSeeLoginButtonEnabled(): Promise<void> {
70	    await expectEnabled(this.loginButton, 'Log in button is enabled');
71	  }
72	
73	  async shouldSeeLoginButtonDisabled(): Promise<void> {
74	    await expectDisabled(this.loginButton, 'Log in button is disabled');
75	  }
76	
77	  async shouldStayOnPage(): Promise<void> {
78	    await expectUrlMatches(this.page, /#\/login$/, 'Login page stays open');
79	  }
80	}
