3	// The shop reads the month of a coupon in capital letters, for example OCT.
4	const COUPON_MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
5	const COUPON_YEAR_DIGITS = 2;
6	const COUPON_PERCENT_DIGITS = 2;
7	
8	// The coupon code is the Z85 encoding of `<MMM><YY>-<NN>` (test-cases/README.md).
9	const buildCouponCode = (monthsFromNow: number, percent: number, now: Date): string => {
10	  const date = new Date(now.getFullYear(), now.getMonth() + monthsFromNow, 1);
11	  const month = COUPON_MONTHS[date.getMonth()];
12	  const year = String(date.getFullYear()).slice(-COUPON_YEAR_DIGITS);
13	  const discount = String(percent).padStart(COUPON_PERCENT_DIGITS, '0');
14	  return z85.encode(`${month}${year}-${discount}`);
15	};
16	
17	// Coupon of the current month, for the server's local time.
18	export const currentMonthCoupon = (percent: number, now: Date = new Date()): string =>
19	  buildCouponCode(0, percent, now);
20	
21	// Coupon of the previous month: the server rejects it as expired.
22	export const previousMonthCoupon = (percent: number, now: Date = new Date()): string =>
23	  buildCouponCode(-1, percent, now);
