export const WALLET_ORDER_TOTAL = '8.99¤';

import { test } from '@/fixtures/customer.fixture';
import { addProductsToBasket } from '@/tests/helpers/customer-setup';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS } from '@/utils/constants/products';

test('Change the quantity and remove a product in the basket', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-03' },
}, async ({ api, customer, loginPage, navbar, basketPage }) => {
  await test.step('Precondition: put product A and product B into the basket', async () => {
    await addProductsToBasket(api, customer, [
      { product: PRODUCTS.raspberry, quantity: 1 },
      { product: PRODUCTS.eggfruit, quantity: 1 },
    ]);
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the basket', async () => {
    await navbar.clickOpenBasket();
    await basketPage.shouldSeeRowCount(2);
    await basketPage.shouldSeeProductRow(PRODUCTS.raspberry, 1);
    await basketPage.shouldSeeProductRow(PRODUCTS.eggfruit, 1);
    await basketPage.shouldSeeTotalPrice('13.98¤');
    await navbar.shouldSeeBasketCounter(2);
  });

  await test.step('2. Click the plus button in the row of product A', async () => {
    await basketPage.clickIncreaseQuantity(PRODUCTS.raspberry);
    await basketPage.shouldSeeProductRow(PRODUCTS.raspberry, 2);
    await basketPage.shouldSeeTotalPrice('18.97¤');
    await navbar.shouldSeeBasketCounter(3);
  });

  await test.step('3. Click the minus button in the row of product A', async () => {
    await basketPage.clickDecreaseQuantity(PRODUCTS.raspberry);
    await basketPage.shouldSeeProductRow(PRODUCTS.raspberry, 1);
    await basketPage.shouldSeeTotalPrice('13.98¤');
    await navbar.shouldSeeBasketCounter(2);
  });

  await test.step('4. Click the minus button in the row of product A again', async () => {
    await basketPage.clickDecreaseQuantity(PRODUCTS.raspberry);
    await basketPage.shouldSeeProductRow(PRODUCTS.raspberry, 1);
    await basketPage.shouldSeeRowCount(2);
    await basketPage.shouldSeeTotalPrice('13.98¤');
  });

  await test.step('5. Click the trash button in the row of product A', async () => {
    await basketPage.clickRemove(PRODUCTS.raspberry);
    await basketPage.shouldNotSeeProductRow(PRODUCTS.raspberry);
    await basketPage.shouldSeeProductRow(PRODUCTS.eggfruit, 1);
    await basketPage.shouldSeeTotalPrice('8.99¤');
    await navbar.shouldSeeBasketCounter(1);
  });
});

