import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS } from '@/utils/constants/products';
import { PURCHASE_LIMIT } from '@/utils/constants/delivery';
import { SHOP_MESSAGES } from '@/utils/constants/shop-messages';

const FIRST_QUANTITY = 1;

test('Purchase limit for one product', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-04' },
}, async ({ customer, loginPage, searchPage, navbar, snackBar, basketPage }) => {
  await test.step('Precondition: log in the new customer with an empty basket', async () => {
    await loginPage.authenticate(customer);
  });

  await test.step('1. Open the product list and click Add to Basket on the product', async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(PRODUCTS.apple);
    await snackBar.shouldSeeMessage(SHOP_MESSAGES.addedToBasket(PRODUCTS.apple.name));
    await navbar.shouldSeeBasketCounter(FIRST_QUANTITY);
  });

  await test.step('2. Open the basket and click the plus button until the quantity is 5', async () => {
    await navbar.clickOpenBasket();
    for (let quantity = FIRST_QUANTITY + 1; quantity <= PURCHASE_LIMIT; quantity += 1) {
      await basketPage.clickIncreaseQuantity(PRODUCTS.apple);
      await basketPage.shouldSeeProductRow(PRODUCTS.apple, quantity);
    }
    await basketPage.shouldSeeTotalPrice('9.95¤');
    await snackBar.shouldNotSeeMessage(SHOP_MESSAGES.purchaseLimit(PURCHASE_LIMIT));
  });

  await test.step('3. Click the plus button one more time', async () => {
    await basketPage.clickIncreaseQuantity(PRODUCTS.apple);
    await snackBar.shouldSeeMessage(SHOP_MESSAGES.purchaseLimit(PURCHASE_LIMIT));
  });

  await test.step('4. Read the basket', async () => {
    await basketPage.shouldSeeProductRow(PRODUCTS.apple, PURCHASE_LIMIT);
    await basketPage.shouldSeeTotalPrice('9.95¤');
    await navbar.shouldSeeBasketCounter(PURCHASE_LIMIT);
  });

  await test.step('5. Open the product list and click Add to Basket on the product', async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(PRODUCTS.apple);
    await snackBar.shouldSeeMessage(SHOP_MESSAGES.purchaseLimit(PURCHASE_LIMIT));
    await navbar.shouldSeeBasketCounter(PURCHASE_LIMIT);
  });
});

import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
