    await navbar.shouldSeeBasketCounter(FIRST_QUANTITY);
  });

  await test.step('2. Open the basket and click the plus button until the quantity is 5', async () => {
    await navbar.clickOpenBasket();
    for (let quantity = FIRST_QUANTITY + 1; quantity <= PURCHASE_LIMIT; quantity += 1) {
      await basketPage.clickIncreaseQuantity(PRODUCTS.apple);
      await basketPage.shouldSeeProductRow(PRODUCTS.apple, quantity);
