import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { CHECKOUT_BUTTON_TEXT } from '@/page-objects/checkout/checkout-button';
import { expectCount, expectEnabled, expectDisabled, expectVisible } from '@/utils/assertions/ui-assertions';
import { SHOP_MESSAGES } from '@/utils/constants/shop-messages';
import { maskedCardNumber } from '@/utils/helpers/customer-data';
import type { SavedCard } from '@/utils/types/customer';

const PAGE_TITLE = 'My Payment Options';
const COUPON_PANEL_NAME = /Add a coupon/;
const COUPON_FIELD_NAME = 'Coupon';
const REDEEM_BUTTON_NAME = 'Redeem';
const DISCOUNT_PREFIX = 'Your discount of';

// The payment step: saved cards, the coupon panel and the wallet payment.
export class PaymentPage extends BasePage {
  private readonly title: Locator;
  private readonly couponPanel: Locator;
  private readonly couponField: Locator;
  private readonly redeemButton: Locator;

  constructor(page: Page) {
    super(page);
    this.title = page.getByRole('heading', { name: PAGE_TITLE, exact: true });
    this.couponPanel = page.getByRole('button', { name: COUPON_PANEL_NAME });
    this.couponField = page.getByRole('textbox', { name: COUPON_FIELD_NAME, exact: true });
    this.redeemButton = page.getByRole('button', { name: REDEEM_BUTTON_NAME, exact: true });
  }

  async selectSavedCard(card: SavedCard): Promise<void> {
    await this.savedCardRow(card).getByRole('radio').click();
  }

  async openCouponPanel(): Promise<void> {
    await this.couponPanel.click();
  }

  async fillCoupon(code: string): Promise<void> {
    await this.couponField.fill(code);
  }

  async clickRedeem(): Promise<void> {
    await this.redeemButton.click();
  }

  async clickWalletPay(price: string): Promise<void> {
    await this.walletPayButton(price).click();
  }

  async clickContinue(): Promise<void> {
    await this.page.locator('button', { hasText: CHECKOUT_BUTTON_TEXT.continue }).click();
  }

  async shouldSeePage(): Promise<void> {
    await expectVisible(this.title, `The page shows the title "${PAGE_TITLE}"`);
  }

  async shouldSeeSavedCard(card: SavedCard): Promise<void> {
    await expectVisible(this.savedCardRow(card), `The page shows the saved card ${maskedCardNumber(card)}`);
  }

  async shouldSeeCouponPanel(): Promise<void> {
    await expectVisible(this.couponPanel, 'The page shows the panel "Add a coupon"');
  }

  async shouldSeeDiscountApplied(percent: number): Promise<void> {
    await expectVisible(
      this.page.getByText(SHOP_MESSAGES.couponApplied(percent), { exact: true }),
      `The page shows "${SHOP_MESSAGES.couponApplied(percent)}"`,
    );
  }

  async shouldNotSeeDiscountApplied(): Promise<void> {
    await expectCount(this.page.getByText(DISCOUNT_PREFIX), 0, 'The page does not show a discount message');
  }

  async shouldSeeInvalidCouponError(): Promise<void> {
    await expectVisible(
      this.page.getByText(SHOP_MESSAGES.invalidCoupon, { exact: true }),
      `The page shows the error "${SHOP_MESSAGES.invalidCoupon}"`,
    );
  }

  async shouldSeeWalletBalance(balance: string): Promise<void> {
    await expectVisible(this.page.getByText(`Wallet Balance ${balance}`), `The wallet balance is ${balance}`);
  }

  async shouldSeeWalletPayEnabled(price: string): Promise<void> {
    await expectEnabled(this.walletPayButton(price), `The button "Pay ${price}" is enabled`);
  }

  async shouldSeeWalletPayDisabled(price: string): Promise<void> {
    await expectDisabled(this.walletPayButton(price), `The button "Pay ${price}" is disabled`);
  }

  private savedCardRow(card: SavedCard): Locator {
    return this.page.getByRole('row').filter({ hasText: maskedCardNumber(card) });
  }

  private walletPayButton(price: string): Locator {
    return this.page.getByRole('button', { name: `Pay ${price}`, exact: true });
  }
}

