import { test } from '@/fixtures/customer.fixture';
import { addProductsToBasket, addSavedAddressAndCard } from '@/tests/helpers/customer-setup';
import { chooseDeliveryAndOpenPayment, openDeliverySpeedStep } from '@/tests/helpers/checkout-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { COUPON_PERCENT, DELIVERY_OPTIONS } from '@/utils/constants/delivery';
import { ORDER_TOTALS } from '@/utils/constants/order-totals';
import { PRODUCTS } from '@/utils/constants/products';
import { SAVED_CARD } from '@/utils/helpers/customer-data';
import { previousMonthCoupon } from '@/utils/helpers/coupon-helper';

const EGGFRUIT_QUANTITY = 2;
const INVALID_CODE = 'abcdefghij';

test('Invalid coupon and expired coupon', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.coupon],
  annotation: { type: 'test-case', description: 'TC-06' },
}, async ({ api, customer, loginPage, basketPage, addressSelectionPage, deliverySpeedPage, paymentPage, orderSummaryPage }) => {
  const pages = { basketPage, addressSelectionPage, deliverySpeedPage, paymentPage };

  await test.step('Precondition: set up the saved address, the saved card and the basket, then log in', async () => {
    await addSavedAddressAndCard(api, customer);
    await addProductsToBasket(api, customer, [{ product: PRODUCTS.eggfruit, quantity: EGGFRUIT_QUANTITY }]);
