import { BasePage } from '@/page-objects/base-page';
import { expectDisabled, expectEnabled, expectUrlMatches, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTES } from '@/utils/constants/ui-routes';
import { SHOP_MESSAGES } from '@/utils/constants/shop-messages';
import type { Customer } from '@/utils/types/customer';
import type { Page } from '@playwright/test';

const LOGIN_TITLE = 'Login';
const INVALID_CREDENTIALS_MESSAGE = SHOP_MESSAGES.invalidCredentials;
const SESSION_TOKEN_KEY = 'token';
const SESSION_BASKET_KEY = 'bid';

export class LoginPage extends BasePage {
  private readonly title;
  private readonly emailField;
  private readonly passwordField;
  private readonly loginButton;
  private readonly errorMessage;

  // appHost is the host of baseURL: the cookie domain of the session.
  constructor(page: Page, private readonly appHost: string) {
    super(page);
    this.title = page.getByRole('heading', { name: LOGIN_TITLE, exact: true });
    this.emailField = page.getByLabel('Text field for the login email');
    this.passwordField = page.getByLabel('Text field for the login password');
    this.loginButton = page.getByRole('button', { name: 'Login', exact: true });
    this.errorMessage = page.getByText(INVALID_CREDENTIALS_MESSAGE);
  }

  async open(): Promise<void> {
    await this.page.goto(UI_ROUTES.login);
    await this.shouldSeePage();
  }

  // A real UI login. Use it only when the login screen is under test (auth-and-sessions.md).
  async login(email: string, password: string): Promise<void> {
    await this.emailField.fill(email);
    await this.passwordField.fill(password);
    await this.loginButton.click();
  }

  // Starts a logged-in session without the UI: the token, the basket id and the cookie go in before the app loads.
  async authenticate(customer: Customer): Promise<void> {
    await this.page.context().addCookies([{ name: SESSION_TOKEN_KEY, value: customer.token, domain: this.appHost, path: '/' }]);
    await this.page.context().addInitScript(
      ({ tokenKey, basketKey, token, basketId }) => {
        localStorage.setItem(tokenKey, token);
        sessionStorage.setItem(basketKey, String(basketId));
      },
      { tokenKey: SESSION_TOKEN_KEY, basketKey: SESSION_BASKET_KEY, token: customer.token, basketId: customer.basketId },
    );
    await this.page.goto(UI_ROUTES.search);
  }

  async shouldSeePage(): Promise<void> {
    await expectVisible(this.title, 'Login page shows the title "Login"');
    await expectVisible(this.emailField, 'Login page shows the field "Email"');
    await expectVisible(this.passwordField, 'Login page shows the field "Password"');
    await expectVisible(this.loginButton, 'Login page shows the button "Log in"');
  }

  async shouldSeeInvalidCredentialsError(): Promise<void> {
    await expectVisible(this.errorMessage, `Login page shows the error "${INVALID_CREDENTIALS_MESSAGE}"`);
  }

  async shouldStayOnPage(): Promise<void> {
    await expectUrlMatches(this.page, /#\/login$/, 'Login page stays open');
  }
}

